        { id: "ssir-grap-strike", name: "Grapple to Strike", description: "Use throws or takedowns to set up ground and pound." },
        { id: "ssir-cage-ctrl", name: "Sand Pit Control", description: "Control the center and force the opponent to the sand pit boundary." },
        { id: "ssir-clinch-dom", name: "Clinch Dominance", description: "Control the head and underhooks to deliver knees or throw." },
        { id: "ssir-guard-pass", name: "Guard Passing", description: "Use pressure and knee slices to pass the guard and advance." },
        { id: "ssir-sub-hunt", name: "Submission Hunting", description: "Chain submissions; if one fails, transition immediately to another." },
        { id: "ssir-sweep-setup", name: "Sweep Setup", description: "Use strikes or feints to hide the foot sweep or trip." },
        { id: "ssir-td-def", name: "Takedown Defense", description: "Sprawl, whizzer, and crossface to stuff shoots and punish." },
        { id: "ssir-gnp", name: "Ground and Pound", description: "Posture up in guard and deliver elbows/punches to force openings." },
        { id: "ssir-wall-walk", name: "Wall Walking", description: "Use the sand pit boundary to stand up when taken down." },
        { id: "ssir-baiting", name: "Baiting", description: "Drop hands slightly to bait a punch, then shoot for the legs." },
        { id: "ssir-level-change", name: "Level Changing", description: "Drop elevation to threaten a takedown, then throw an uppercut." },
        { id: "ssir-chain-wrest", name: "Chain Wrestling", description: "If single leg fails, transition to high crotch or ankle pick." },
        { id: "ssir-guard-ret", name: "Guard Retention", description: "Use knee shields and hip escapes to prevent guard passes." },
        { id: "ssir-pos-hier", name: "Positional Hierarchy", description: "Prioritize back control > mount > side control > guard." },
        { id: "ssir-pace-break", name: "Pace Breaking", description: "Change rhythm from slow stalking to explosive blitzes." },
        { id: "ssir-feinting", name: "Feinting", description: "Fake a jab to draw a high guard, then shoot for the legs." },
        { id: "ssir-framing", name: "Framing", description: "Use skeletal structure to create space and prevent crushing pressure." },
        { id: "ssir-grip-fight", name: "Grip Fighting", description: "Clear opponent's grips in the clinch to secure your own throws." },
        { id: "ssir-energy-cons", name: "Energy Conservation", description: "Relax in the clinch and guard; only explode during transitions." }
